using System; using System.Collections.Generic; using System.Linq;
using System.Text.Json; using System.Threading; using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class SimpsonJob : IAgentComputation
{
    static double F(double x) => Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2.0 * x));

    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int k = input.WorkerIndex;
        double a = 8.0 * k / 2.0;
        double b = 8.0 * (k + 1) / 2.0;
        int n = 10000;
        double h = (b - a) / n;
        double s = F(a) + F(b);
        for (int i = 1; i < n; i++)
        {
            double x = a + i * h;
            s += (i % 2 == 1 ? 4.0 : 2.0) * F(x);
        }
        double integral = s * h / 3.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new SubResult { k = k, a = a, b = b, value = integral })));
    }
}

public class SubResult
{
    public int k { get; set; }
    public double a { get; set; }
    public double b { get; set; }
    public double value { get; set; }
}

public class ReduceJob : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double total = 0.0;
        var parts = new List<SubResult>();
        for (int j = 0; j < 2; j++)
        {
            var outs = input.GetPreviousOutputs(j);
            if (outs == null) return Task.FromResult(AgentLayerResult.Error("parent " + j + " missing"));
            foreach (var o in outs)
            {
                if (o == null) return Task.FromResult(AgentLayerResult.Error("parent " + j + " has failed worker"));
                var r = JsonSerializer.Deserialize<SubResult>(o);
                parts.Add(r);
                total += r.value;
            }
        }
        parts.Sort((x, y) => x.k.CompareTo(y.k));
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new
        {
            integral = total,
            I = total.ToString("R"),
            parts = parts.Select(p => new { p.k, p.a, p.b, p.value }).ToList()
        })));
    }
}

